function newCompanyData(meta){
  return {
    id:meta.id,name:meta.name,industry:meta.industry||'',color:meta.color||'#1EB682',initial:meta.initial||meta.name.slice(0,2).toUpperCase(),
    npwp:meta.npwp||'',fiscalStart:meta.fiscalStart||1,currency:'IDR',createdAt:new Date().toISOString(),
    coa:DEFAULT_COA(),
    journal:[],sales:[],purchases:[],cashbank:[],contacts:[],inventory:[],inventoryLogs:[],fixedAssets:[],
    counters:{sales:0,purchase:0,cashbank:0,journal:0,asset:0,item:0,contact:0}
  };
}

